def priority(task, state, age=2.0, guard=2.0, tier=2.0, qlen_thresh=10.0, backoff=0.5):
    import math
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    ratio = wait / est
    tier_mult = tier if task.tenant == 'premium' else 1.0
    # under heavy queue, favor short jobs more aggressively
    if state.queue_len > qlen_thresh:
        est_eff = est * backoff
    else:
        est_eff = est
    score = tier_mult * task.weight / est_eff * (1.0 + age * ratio)
    if ratio >= guard:
        score += 1e6
    return score  # tuned (age=7.15,guard=0.725,tier=1.72,qlen_thresh=14.8,backoff=0.568)

def priority(task, state, b=0.5, m=2.0, q_lo=0.5, q_hi=0.9):
    wait = state.now - task.release
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    ratio = wait / est
    base = tier * task.weight / est * (1.0 + b * ratio)
    # When queue is heavily loaded, prioritize by lateness ratio instead
    load = state.queue_work / max(state.capacity, 1e-6)
    if load > q_hi:
        return base + 1000.0 * max(0.0, ratio - 1.0)
    if load > q_lo:
        return base * (1.0 + ratio)
    return base  # tuned (b=0.903,m=1.51,q_lo=0.527,q_hi=1.53)

import math
def priority(task, state, b=1.0, c=2.0, boost=1e6, m=1.3, k=2.5):
    wait = state.now - task.release
    est = max(task.estimated_runtime, 1e-6)
    ratio = wait / est
    tier = m if task.tenant == 'premium' else 1.0
    # base aging WSPT
    base = task.weight / est * (1.0 + b * ratio)
    # SLO guard: hard boost past c*est, mild boost in [0.5c, c)
    if ratio >= c:
        guard = boost
    elif ratio >= 0.5 * c:
        guard = boost * 0.1 * (ratio - 0.5 * c) / (0.5 * c)
    else:
        guard = 0.0
    # slack-based urgency only for requests with negative/near-zero slack
    slack = task.due - est - state.now
    if slack < 0:
        urgency = task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    else:
        urgency = 0.0
    return guard + tier * (base + 0.3 * urgency)  # tuned (b=0.755,c=1.04,boost=1.02e+06,m=0.405,k=9.1)
